import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toLong()

    st = StringTokenizer(br.readLine())
    val a = IntArray(n) { st.nextToken().toInt() }

    st = StringTokenizer(br.readLine())
    val b = IntArray(n) { st.nextToken().toInt() }

    // Precompute minimal cost for each position modulo n and balance
    // dp[posMod][balance] = minimal cost to choose bracket at this position with given balance
    // balance range: 0..n (safe upper bound, since n<=20 and we only need up to m which is large,
    // but balance in any regular sequence never exceeds m/2, and we only use transitions that keep it valid)
    val maxBalance = n
    val INF = Long.MAX_VALUE / 4
    val dp = Array(n) { LongArray(maxBalance + 1) { INF } }

    for (posMod in 0 until n) {
        for (bal in 0..maxBalance) {
            var best = INF
            // Try '('
            if (bal + 1 <= maxBalance) {
                val costOpen = a[posMod]
                if (costOpen < best) best = costOpen.toLong()
            }
            // Try ')'
            if (bal > 0) {
                val costClose = b[posMod]
                if (costClose < best) best = costClose.toLong()
            }
            dp[posMod][bal] = best
        }
    }

    // Now dynamic programming over positions using periodicity of n.
    // We only need to track balance; cost per step depends on posMod and choice.
    // But we must ensure sequence is regular: never negative balance, end with 0.
    // We'll use DP over one period (n steps) as a transition matrix on balances,
    // then exponentiate for m steps using binary lifting on periods.

    // First, compute transition for one position: from balance to next balance with minimal added cost.
    // trans[posMod][bal] = Pair(nextBal, addCost)
    data class Transition(val nextBal: Int, val addCost: Long)
    val trans = Array(n) { Array(maxBalance + 1) { Transition(0, INF) } }

    for (posMod in 0 until n) {
        for (bal in 0..maxBalance) {
            var bestCost = INF
            var bestNext = -1
            // '('
            if (bal + 1 <= maxBalance) {
                val c = a[posMod].toLong()
                if (c < bestCost) {
                    bestCost = c
                    bestNext = bal + 1
                }
            }
            // ')'
            if (bal > 0) {
                val c = b[posMod].toLong()
                if (c < bestCost) {
                    bestCost = c
                    bestNext = bal - 1
                }
            }
            if (bestNext == -1) {
                trans[posMod][bal] = Transition(bal, INF)
            } else {
                trans[posMod][bal] = Transition(bestNext, bestCost)
            }
        }
    }

    // DP over one full period of n positions: from balance to balance with minimal cost
    val periodTrans = Array(maxBalance + 1) { LongArray(maxBalance + 1) { INF } }
    for (startBal in 0..maxBalance) {
        var curBal = startBal
        var totalCost = 0L
        var valid = true
        for (posMod in 0 until n) {
            val t = trans[posMod][curBal]
            if (t.addCost >= INF) {
                valid = false
                break
            }
            totalCost += t.addCost
            curBal = t.nextBal
            if (curBal < 0 || curBal > maxBalance) {
                valid = false
                break
            }
        }
        if (valid) {
            periodTrans[startBal][curBal] = minOf(periodTrans[startBal][curBal], totalCost)
        }
    }

    // Binary lifting over periods
    val periods = (m / n).toInt()
    val remainder = (m % n).toInt()

    // lift[k][from][to]: minimal cost to go from balance 'from' to 'to' in 2^k periods
    val maxK = 32
    val lift = Array(maxK) { Array(maxBalance + 1) { LongArray(maxBalance + 1) { INF } } }

    // k = 0: one period
    for (i in 0..maxBalance) {
        for (j in 0..maxBalance) {
            lift[0][i][j] = periodTrans[i][j]
        }
    }

    // Build higher powers
    for (k in 1 until maxK) {
        for (i in 0..maxBalance) {
            for (j in 0..maxBalance) {
                var best = INF
                for (mid in 0..maxBalance) {
                    val c1 = lift[k - 1][i][mid]
                    if (c1 >= INF) continue
                    val c2 = lift[k - 1][mid][j]
                    if (c2 >= INF) continue
                    val sum = c1 + c2
                    if (sum < best) best = sum
                }
                lift[k][i][j] = best
            }
        }
    }

    // Apply periods starting from balance 0
    var curBal = 0
    var answer = 0L
    var p = periods
    var k = 0
    while (p > 0) {
        if ((p and 1) == 1) {
            // apply 2^k periods
            var bestNextBal = -1
            var bestCost = INF
            for (to in 0..maxBalance) {
                val c = lift[k][curBal][to]
                if (c < bestCost) {
                    bestCost = c
                    bestNextBal = to
                }
            }
            if (bestNextBal == -1 || bestCost >= INF) {
                println(-1)
                return
            }
            answer += bestCost
            curBal = bestNextBal
        }
        p = p shr 1
        k++
    }

    // Handle remaining positions (remainder < n) directly
    for (pos in 0 until remainder) {
        val posMod = pos % n
        val t = trans[posMod][curBal]
        if (t.addCost >= INF) {
            println(-1)
            return
        }
        answer += t.addCost
        curBal = t.nextBal
        if (curBal < 0 || curBal > maxBalance) {
            println(-1)
            return
        }
    }

    // Must end with balance 0
    if (curBal != 0) {
        println(-1)
        return
    }

    println(answer)
}

