    val T = Array(maxBalance + 1) { LongArray(maxBalance + 1) { INF } }
    for (bal in 0..maxBalance) {
        for (newBal in 0..maxBalance) {
            T[bal][newBal] = dp[0][newBal] // starting posMod=0
        }
    }

    // exponentiate T by 'blocks' using DP over balances
    fun applyTransition(state: LongArray, trans: Array<LongArray>): LongArray {
        val res = LongArray(maxBalance + 1) { INF }
        for (i in 0..maxBalance) {
            val cur = state[i]
            if (cur == INF) continue
            val row = trans[i]
            for (j in 0..maxBalance) {
                val v = row[j]
                if (v == INF) continue
                val cost = cur + v
                if (cost < res[j]) res[j] = cost
            }
        }
