    var first = true
    var accTrans = Array(maxBalance + 1) { LongArray(maxBalance + 1) { if (it == 0) 0L else INF } }

    // identity matrix
    for (i in 0..maxBalance) {
        for (j in 0..maxBalance) {
            accTrans[i][j] = if (i == j) 0L else INF
        }
    }

    var baseTrans = T
